hooks.command:
python3 -c "
import sys, json
data = json.load(sys.stdin)
cmd = data.get('tool_input', {}).get('command', '').lower()
protected = ['spendly.db', '.env', 'migrations/']
dangerous = ['rm ', 'rm -', 'unlink ', 'truncate ', 'remove-item', 'del ', 'clear-content', 'move-item', 'rename-item', 'mv ']
for d in dangerous:
    if d in cmd:
        for p in protected:
            if p in cmd:
                print(f'BLOCKED: Cannot run destructive command on protected file: {p}', file=__import__(\"sys\").stderr)
                raise SystemExit(2)
"
